import unittest
import lib_d84bcdd9 as m


class Hidden(unittest.TestCase):
    def test_behavior(self):
        chain = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta', '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0', '1.0.1', '1.2.0', '1.10.0', '2.0.0']
        for i, a in enumerate(chain):
            for j, b in enumerate(chain):
                self.assertEqual(m.compare(a, b), (i > j) - (i < j), (a, b))
        for a, b, want in [('2.6.5-x.7', '2.6.5-x.7+build.5', 0), ('5.10.3-rc.1', '5.9.10-beta', 1), ('3.3.10-2', '6.6.6', -1), ('0.0.5-2', '8.8.4-11', -1), ('9.11.10-alpha', '3.0.6-11', 1), ('0.4.10-x.7', '4.1.9-rc.10', -1), ('10.3.8-alpha', '0.1.2-rc.10', 1), ('6.2.10', '5.4.6', 1), ('8.7.8-2', '1.8.0-11', 1), ('11.10.4-rc.1', '6.11.2-beta', 1), ('1.2.8', '5.11.6-beta', -1), ('12.9.6-alpha', '11.11.3-rc.10', 1), ('0.7.3-alpha', '0.12.0', -1), ('9.8.8-alpha', '2.10.7-beta', 1), ('11.5.12-alpha', '9.5.11-rc.10', 1), ('9.11.3', '9.11.3+build.5', 0), ('0.5.8-rc.1', '0.5.8-rc.1+build.5', 0), ('11.8.10-rc.1', '11.8.10-rc.1+build.5', 0), ('1.3.9-2', '1.7.9-beta', -1), ('10.11.9', '7.5.2-rc.10', 1), ('11.2.8-alpha', '11.12.6-beta', -1), ('1.0.2', '11.7.6-11', -1), ('12.6.0-alpha', '8.11.9', 1), ('0.2.11-2', '7.9.7-11', -1), ('10.8.7', '10.8.7+build.5', 0), ('5.1.4-rc.1', '5.1.4-rc.1+build.5', 0), ('7.1.8-rc.1', '12.10.7', -1), ('7.12.11-x.7', '11.10.1-rc.10', -1), ('3.4.3', '3.4.3+build.5', 0), ('0.4.6-2', '2.3.2-beta', -1), ('4.12.12-2', '1.9.8-beta', 1), ('6.0.9-rc.1', '6.1.1-rc.10', -1), ('5.6.6', '8.11.7-11', -1), ('1.10.0-rc.1', '1.10.0-rc.1+build.5', 0), ('0.11.7-2', '6.9.7-beta', -1), ('9.5.10-rc.1', '8.4.5-11', 1), ('9.2.0-alpha', '1.11.7-11', 1), ('7.5.9-2', '7.1.3-beta', 1), ('7.1.12', '10.4.5', -1), ('9.3.8-2', '5.1.9-11', 1), ('2.9.5', '12.7.3', -1), ('6.6.4-rc.1', '3.12.6-rc.10', 1), ('5.11.9-rc.1', '5.11.9-rc.1+build.5', 0), ('11.7.2-2', '8.2.12', 1), ('5.7.6', '2.5.9-rc.10', 1), ('0.9.10', '8.3.6-11', -1), ('1.12.9-2', '6.2.4-rc.10', -1), ('1.4.4-alpha', '4.12.5-11', -1), ('11.11.1-2', '12.2.12-beta', -1), ('9.5.7-rc.1', '9.4.5', 1), ('9.7.11-x.7', '7.3.12-11', 1), ('1.1.11-rc.1', '8.8.2', -1), ('5.5.8-alpha', '10.6.12-beta', -1), ('4.11.0-x.7', '5.12.1', -1), ('2.2.5-rc.1', '9.10.6-rc.10', -1), ('7.3.10', '12.12.11', -1), ('5.0.4-rc.1', '5.0.4-rc.1+build.5', 0), ('6.10.1-rc.1', '2.11.7', 1), ('1.2.0-2', '1.2.0-2+build.5', 0), ('4.4.9-alpha', '3.4.10-rc.10', 1)]:
            self.assertEqual(m.compare(a, b), want, (a, b))
        for bad in ['1.0', '01.0.0', '1.0.0-', '1.0.0-01', 'v1.0.0', '', '1.0.0+']:
            with self.assertRaises(ValueError):
                m.compare(bad, '1.0.0')


if __name__ == "__main__":
    unittest.main()
